style.css:
/* ? TikTok Rosa Pastel com Stylish */

/* Fundo geral */
body {
  background-color: #ffe4ec !important; /* rosa pastel */
  font-family: 'Poppins', sans-serif !important;
  color: #5c3d4e !important; /* tom roxo suave para contraste */
}

/* Barra lateral e menus */
div[data-e2e="right-sidebar-container"],
div[data-e2e="left-sidebar-container"] {
  background-color: #ffd6e0 !important; /* rosa mais claro */
  border-radius: 12px !important;
}

/* Botões */
button {
  background-color: #ffb6c1 !important; /* rosa bebê */
  color: #fff !important;
  border-radius: 20px !important;
  padding: 8px 14px !important;
  border: none !important;
  box-shadow: 0 4px 8px rgba(255, 182, 193, 0.4) !important;
}

/* Links */
a {
  color: #ff69b4 !important; /* rosa chiclete */
}

/* Vídeos com moldura pastel */
video {
  border-radius: 18px !important;
  box-shadow: 0 0 20px rgba(255, 182, 193, 0.6) !important;
  border: 4px solid #ffe4ec !important;
}

/* Cabeçalhos e textos */
h1, h2, h3, h4, h5, h6 {
  color: #d36b8c !important; /* rosa mais forte */
}

/* Esconder anúncios */
div[class*="ad"] {
  display: none !important;
}

/* Ícones e elementos extras */
svg, i {
  color: #ff9aa2 !important; /* rosa pastel suave */
}
